function model(p) {
  // Illustrative 3D "embeddings": hand-placed synthetic unit vectors, not output of a real embedding model
  // (real ones have hundreds of dimensions). Each chunk is [title, topic, u, v]: a position on a map that is
  // lifted onto the unit sphere, so nearby map positions mean similar directions.
  const TOPICS = ['HR leave', 'Travel expenses', 'IT security'];
  const CHUNKS = [
    ['Parental leave: 16 weeks', 0, 0.05, 1.05], ['Annual leave allowance', 0, 0.25, 0.95], ['Sick leave and doctor\u2019s note', 0, -0.22, 1.22],
    ['Carrying over unused days', 0, 0.42, 1.18], ['Bereavement leave', 0, -0.42, 1.0], ['Booking leave in the HR portal', 0, 0.3, 0.68],
    ['Unpaid sabbatical', 0, 0.05, 1.48], ['Public holiday calendar', 0, -0.3, 0.7],
    ['Taxis and ride-share', 1, -0.72, -0.45], ['Receipts and claim deadline', 1, -0.62, -0.7], ['Mileage for your own car', 1, -0.87, -0.25],
    ['Booking flights and hotels', 1, -1.17, -0.4], ['Daily meal allowance', 1, -0.92, -0.85], ['Travel insurance cover', 1, -0.74, 0.0],
    ['When business class is allowed', 1, -1.32, -0.65], ['Client entertainment limits', 1, -1.17, -0.95],
    ['Reporting phishing emails', 2, 0.77, -0.45], ['Security incident hotline', 2, 0.99, -0.35], ['Passwords and MFA', 2, 0.72, -0.78],
    ['Lost or stolen laptop', 2, 1.17, -0.6], ['Approved software list', 2, 0.97, -0.95], ['Classifying confidential data', 2, 1.12, -0.12],
    ['USB drives and removable media', 2, 1.32, -0.85], ['VPN on public Wi-Fi', 2, -0.24, -0.66]
  ];
  const QUESTIONS = [
    ['How many weeks of parental leave do I get?', 0, 0.12, 1.0],
    ['Can I expense a taxi from the airport?', 1, -0.68, -0.5],
    ['I clicked a link in a phishing email. What now?', 2, 0.85, -0.42]
  ];
  const norm = v => { const l = Math.hypot(v[0], v[1], v[2]); return v.map(x => x / l); };
  const n = norm([1, 1, 1]), e1 = norm([1, -1, 0]), e2 = [n[1] * e1[2] - n[2] * e1[1], n[2] * e1[0] - n[0] * e1[2], n[0] * e1[1] - n[1] * e1[0]];
  const A = 0.9; // radians of arc per map unit
  const lift = (u, v) => { const r = Math.hypot(u, v) || 1e-9, th = r * A; return [0, 1, 2].map(i => +(Math.cos(th) * n[i] + Math.sin(th) * (u * e1[i] + v * e2[i]) / r).toFixed(4)); };
  const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const cos = (a, b) => dot(a, b) / (Math.hypot(...a) * Math.hypot(...b));
  // 2D view: orthographic projection onto the plane facing (1,1,1); it distorts distances a little
  const proj = v => [+dot(v, e1).toFixed(4), +dot(v, e2).toFixed(4)];
  const qi = Math.max(0, Math.min(2, Math.round(p.question)));
  const [qText, qTopic, qu, qv] = QUESTIONS[qi];
  const qvec = lift(qu, qv);
  const chunks = CHUNKS.map(([title, topic, u, v], id) => {
    const vec = lift(u, v);
    return { id, title, topic, topicName: TOPICS[topic], vec, xy: proj(vec), sim: +cos(qvec, vec).toFixed(6) };
  });
  const ranked = chunks.slice().sort((a, b) => b.sim - a.sim || a.id - b.id);
  ranked.forEach((ch, i) => { ch.rank = i + 1; });
  const k = Math.max(1, Math.min(6, Math.round(p.topK)));
  const context = ranked.slice(0, k);
  const off = context.filter(ch => ch.topic !== qTopic);
  const duration = 12, markers = [0, 2.2, 3.6, 7, 9];
  const lower = ['HR leave', 'travel expenses', 'IT security'][qTopic];
  const summary = 'Top ' + k + ': ' + (off.length ? (k - off.length) + ' about ' + lower + ' plus ' + off.length + ' off-topic (' + off.map(c => c.title).join(', ') + ')' : 'all about ' + lower) +
    ', cosine ' + context[0].sim.toFixed(3) + (k > 1 ? ' to ' + context[k - 1].sim.toFixed(3) : '') + '. Only ' + (k > 1 ? 'these ' + k + ' passages reach' : 'this passage reaches') + ' the model.';
  return {
    topics: TOPICS, chunks, ranked, context, k, offTopic: off.length,
    question: { index: qi, text: qText, topic: qTopic, topicName: TOPICS[qTopic], vec: qvec, xy: proj(qvec) },
    basis: { e1: e1.map(x => +x.toFixed(6)), e2: e2.map(x => +x.toFixed(6)), n: n.map(x => +x.toFixed(6)) },
    phases: { chunks: [0, 2.2], question: [2.2, 3.6], rank: [3.6, 7], topk: [7, 9], context: [9, 12] },
    duration, markers, summary
  };
}

