function check(p) {
  const m = model(p), q = m.question.vec;
  const cosine = (a, b) => { let d = 0, na = 0, nb = 0; for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; } return d / Math.sqrt(na * nb); };
  const err = Math.max(...m.chunks.map(c => Math.abs(cosine(q, c.vec) - c.sim)));
  const kept = new Set(m.context.map(c => c.id)), rest = m.chunks.filter(c => !kept.has(c.id));
  const minKept = Math.min(...m.context.map(c => c.sim)), maxRest = Math.max(...rest.map(c => c.sim));
  const topOk = m.context.length === Math.max(1, Math.min(6, Math.round(p.topK))) && minKept >= maxRest &&
    m.context.every((c, i) => i === 0 || m.context[i - 1].sim >= c.sim);
  const perQ = [0, 1, 2].map(i => { const mi = model(Object.assign({}, p, { question: i })); return mi.ranked[0].topic === mi.question.topic; });
  return {
    pass: err < 1e-5 && topOk && perQ.every(Boolean),
    detail: 'All ' + m.chunks.length + ' similarities equal dot(q, c)/(|q||c|) to within ' + err.toExponential(1) + '; the ' + (m.k > 1 ? m.k + ' kept passages score ' : 'kept passage scores ') +
      minKept.toFixed(3) + ' or more versus at most ' + maxRest.toFixed(3) + ' for the rest; the top hit is on-topic for ' + perQ.filter(Boolean).length + ' of 3 questions.'
  };
}
